/** Exact Director birth/retirement extraction. Ordinary native fallback retained. */
export const nativeDirectorBirthSourceArchive={"pin":"484f9263","nativeHash":"504e59ea5edd61d055e011a50386b44aafa5db44b1093ed268207b6bcc710d2d","predecessor":"// ---------------------------------------------------------------------------\n// THE SCENE DIRECTOR — engine half of the scene fabric (data/scenes.ts).\n//\n// A scene is a stage list walked in order by ONE driver (updateScene), hooked\n// into World.update on the RAW clock — before the timeflow gate's early\n// return — because scenes OWN their holds: a card freezes the whole sim\n// under itself, the reckoning freezes everyone but the executioner, and the\n// director must keep breathing through both. Scenes yield only to the true\n// pause (a 'menu' hold).\n//\n// Stage kinds are an OPEN REGISTRY (registerSceneStage) — the core six ship\n// here; a new cinematic beat is a kind + a handler. Handlers speak to the\n// World through its ordinary public surface: scene spawns ride createMonster\n// + the wave-frenzy overlay (already-hunting), the executioner's verb rides\n// useSkill (cast bar + telegraph honest by construction), the staging ground\n// rides mintCave into the OFF-GRAPH caveMap (never serialized, culled from\n// any save that claims it), and teardown is one surface loadZone home.\n//\n// THE COVENANT: nobody truly dies on scripted ground. Every player-seat\n// lethal blow routes through World.onPlayerDown, whose head asks this module\n// first (sceneInterceptFall) — the seat is FELLED bodily (the world's own\n// downed state: inputs, regeneration and re-kills all refused), never\n// killed; once no seat stands, the script LANDS on the nearest stage that\n// narrates a wake (the card) — or plays the fall in place where a stage\n// knows how (the reckoning). A stage upstream of the fall never plays: the\n// Father is a wall you reach alive, never a summons. And nothing on\n// scripted ground pays: every scene spawn is\n// stamped noBounty (no xp, loot, gems, or orbs) on rewardless 'none'-spoils\n// ground — introductions are the whole reward.\n//\n// THE RUN BEGINS AFTER: a scene is not a run. While one plays, the shell\n// writes no run save (startGame's baseline, the autosave cadence, the menu\n// exit and the quit flush all stand down), World.endRun refuses the forfeit\n// ceremony, and the completion stamp + the run's FIRST save both land at\n// the 'home' stage — so an abort leaves nothing to resume and the next New\n// Game re-launches the scene (the begun-key keeps it due).\n// ---------------------------------------------------------------------------\n\nimport type { World,Seat } from './world';\nimport type {NativeSceneDirectorHost} from './nativeSceneDirectorHost';\nimport type { Actor } from './actor';\nimport type { ZoneDef } from '../data/zones';\nimport { START_ZONE } from '../data/zones';\nimport {\n  SCENES, SCENE_CFG, type SceneDef, type SceneStage, type SceneCardSpec,\n  type SceneCardStage, type SceneDrillStage, type SceneClashStage,\n  type SceneAssaultStage, type SceneReckoningStage, type SceneMuStage,\n  type SceneSpawnRow, type SceneZoneSpec,\n} from '../data/scenes';\nimport {\n  MU_CFG, MU_SCENE_ID, MU_ZONE, apparitionDefId, APPARITION_UNKNOWN_ID,\n} from '../data/mu';\nimport { muDeal } from './muDeal';\nimport { muRings } from './muRing';\nimport { MODE_BY_ID } from '../meta/modes';\nimport { WAVE_CFG } from '../data/waves';\nimport { mintCave } from './worldgen';\nimport { makeSkillInstance } from './skills';\nimport { SKILLS } from '../data/skills';\nimport { doodadRuleOf, type Doodad } from './levelgen';\nimport { LEDGER_FLASK_LESSON, type Account } from '../meta/account'; // the hand's reads moved to muDeal.ts\nimport { bumpLedger } from '../packages/ledger';\nimport { registerAttentionSource } from '../world/attention';\nimport { Rng } from '../core/rng';\nimport { vec, dist, rand, angleDiff, type Vec2 } from '../core/math';\nimport { DAY_LENGTH } from '../world/daynight';\nimport { beginSceneRoad, streamSceneRoad, sceneRoadShoulder, sceneRoadCoordinates, onSceneRoad, type SceneRoad } from './sceneRoad';\n\n// ------------------------------------------------------------- the runtime --\n\n/** Live state of the one running scene (World.scene). The HUD channels\n *  (bar/prompt/focus/card) are read by the renderer + DOM layer each frame —\n *  drawn state IS director state, nothing forked. */\nexport interface SceneRuntime {\n  road?: SceneRoad;\n  /** Scene-local day wheel, used only while standing on the staging ground. */\n  skyTime?: number;\n  /** Retained unfinished narrative goal during the commander's interruption. */\n  interruptedObjective?: { label: string; frac: number };\n  def: SceneDef;\n  zoneId: string;\n  stageIx: number;\n  /** Seconds inside the current stage (raw clock — holds don't stop it). */\n  stageT: number;\n  begun: boolean;\n  /** Per-stage scratch, cleared on advance. */\n  state: Record<string, unknown>;\n  /** The hero has been felled (scripted — never a real death). */\n  fell: boolean;\n  /** Lifetime seat-pressed casts (the drill reads deltas). */\n  casts: number;\n  /** Scene HUD bar (label + 0..1). */\n  bar: { label: string; frac: number } | null;\n  /** Scene HUD prompt line ('{bind:…}' tokens resolve at draw). */\n  prompt: string | null;\n  /** Where the bar + prompt sit: 'hero' floats just above the player's\n   *  head (teaching at the eye), 'top' takes the encounter bar's screen\n   *  seat (the assault's dawn clock). Stage handlers set it per beat. */\n  barAt: 'hero' | 'top';\n  /** Cinematic camera override — the renderer follows this instead of the\n   *  hero while set. */\n  focus: Vec2 | null;\n  /** THE MARK (the agency reckoning): a live actor the attention fabric\n   *  points at while it stands — the chevron that says GO STOP HIM. The\n   *  source registered below resolves it fresh every frame; off-screen only\n   *  by the fabric's own law. Cleared on stage advance. */\n  mark: { id: number; color: string } | null;\n  /** THE HUD VEIL (the Mu stage): hide the run HUD cluster while this stage\n   *  plays — a spirit carries no life, no flasks, no bar. The scene's own\n   *  channels (bar/prompt/card) keep drawing. Cleared on stage advance. */\n  hudVeil: boolean;\n  /** THE PANEL SEAL (the Mu stage — MU_CFG.sealPanels, her lever): hero\n   *  pages the shell keeps SHUT while this stage plays (menu-entry ids,\n   *  data/menu.ts) and the refusal line the press hears. Null = nothing\n   *  sealed. Cleared on stage advance like the veil. */\n  panelSeal: { ids: ReadonlySet<string>; line: string; ink: string } | null;\n  /** Pending story card (the DOM layer shows it; ack via sceneCardAck). */\n  card: SceneCardSpec | null;\n  cardAck: boolean;\n  /** Director-owned screen fade target (0 world, 1 black). */\n  fadeTarget: number;\n  /** THE FUNERAL BEAT: a bodily fall just landed the script on a stage —\n   *  the dark is OWED but not yet due (the world breathes over the body for\n   *  SCENE_CFG.fallWaitSec first). The landing stage clears it. */\n  fallBeat: boolean;\n  /** The current stage was reached BY A FALL from upstream — the stages\n   *  between never played (the prologue: the Father was never met). A\n   *  landing card may speak differently to it. Cleared on stage advance. */\n  landed: boolean;\n  /** Stamp worn by every scene spawn — the sweepable scope. */\n  eventKey: string;\n  /** THE FAR-FIELD DRESS (boundless stages): the heart-sampled palette +\n   *  the seeded-chunk ledger. Built at sceneBegin on boundless stages\n   *  only; absent = the streamer is inert (walled stages unchanged). */\n  dress?: SceneDressState;\n}\n\n/** The far-field dress streamer's state (streamSceneDress): what the minted\n *  heart taught us to scatter, and which chunks already carry it. */\nexport interface SceneDressState {\n  /** One row per streamable heart kind: radius band, whether instances\n   *  spin, and the expected pieces per chunk at far-field density. */\n  palette: { kind: Doodad['kind']; rMin: number; rMax: number; rot: boolean; perChunk: number }[];\n  /** Seeded chunks, \"cx,cy\" → the pieces this chunk put on the ground\n   *  (empty array = seeded-and-blank: the heart's footprint, or a roll\n   *  that placed nothing — either way, never re-rolled while it stands). */\n  chunks: Map<string, Doodad[]>;\n  /** The authored heart's footprint (the minted arena) — its chunks are\n   *  already dressed by generation and stay the streamer's no-go rect. */\n  heart: { w: number; h: number };\n}\n\n/** One registered stage kind. `update` runs every raw-clock tick; return\n *  true when the stage completes. `onFell` says what a felled FIELD (every\n *  seat down) means to the stage: 'skip' — the fall passes over it (the\n *  teaching beats); 'play' — a fall WHILE it runs is played in place, but\n *  it is never a landing for a fall from upstream (the reckoning: the\n *  Father is the wall you reach alive, never a summons); 'land' — the\n *  fall's destination, the nearest one downstream (the card that narrates\n *  the wake). */\nexport interface SceneStageHandler {\n  begin?(w: NativeSceneDirectorHost, sc: SceneRuntime, spec: SceneStage): void;\n  update(w: NativeSceneDirectorHost, sc: SceneRuntime, spec: SceneStage, dt: number): boolean;\n  onFell?: 'skip' | 'play' | 'land';\n}\n\nconst STAGES: Record<string, SceneStageHandler> = {};\n\nexport function registerSceneStage(kind: string, h: SceneStageHandler): void {\n  STAGES[kind] = h;\n}\n\n// ------------------------------------------------------------ gate + begin --\n\n/** The 'walked in but never walked out' key: stamped at scene START, it\n *  keeps an ABORTED scene due — quitting mid-tutorial and starting a new\n *  game re-launches it, whatever the aborted attempt drifted on the account\n *  (a roster vessel, a stray credit). Only completion closes the door. */\nexport const sceneBegunKey = (def: SceneDef): string => `${def.ledger}_begun`;\n\n/** Is this scene DUE for the account? The scene only COUNTS once completed\n *  (its `ledger` key stamps at the 'home' stage): until then it stays due\n *  for a virgin account — or for any account that BEGAN it and aborted.\n *  Veterans predating a newly-added scene are grandfathered by their own\n *  history, no migration write needed. (A full account reset births a\n *  virgin account: scenes return with it.) */\nexport function sceneDue(account: Account, id: string): boolean {\n  const def = SCENES[id];\n  // A transient scene sits outside the gate whole: never DUE (the shell\n  // begins it deliberately), never stamped, never counted.\n  if (!def || def.transient) return false;\n  if (account.ledger[def.ledger] ?? 0) return false;\n  if (account.ledger[sceneBegunKey(def)] ?? 0) return true;\n  return account.roster.length === 0 && account.deaths.length === 0\n    && account.lifetimeCredits === 0\n    && !(account.ledger[LEDGER_FLASK_LESSON] ?? 0);\n}\n\n/** Begin a scene: stamp the gate, mint the staging ground OFF-GRAPH, and\n *  step through under black. Call with the hero standing in the zone the\n *  scene should return to (the prologue: the fresh run's town). */\nexport function sceneBegin(w: NativeSceneDirectorHost, id: string): boolean {\n  const def = SCENES[id];\n  if (!def || w.scene) return false;\n  // THE RESOLVE SEAM: the runtime walks the EFFECTIVE def (the tutorial\n  // factions swap stage rows per the account's rolled legion); the gate\n  // stamps below keep reading the BASE def — id and ledger never move.\n  const eff = def.resolve ? def.resolve(w, def) : def;\n  // The BEGUN mark (never the completion key): the scene doesn't COUNT\n  // until it is lived to the end — an abort re-launches it on the next New\n  // Game. While a scene runs, the shell suppresses every run save (the\n  // tutorial is not a run; the run begins at 'home'), so a mid-scene quit\n  // leaves nothing to resume into. A TRANSIENT scene (the Mu hub) stamps\n  // nothing at all — enterable forever, invisible to the gate.\n  if (!def.transient && !(w.account.ledger[sceneBegunKey(def)] ?? 0)) {\n    bumpLedger(w.account.ledger, sceneBegunKey(def));\n    w.accountDirty = true;\n  }\n  const zid = `scene_${id}`;\n  const parent = w.zone;\n  const z = mintCave(parent, eff.zone.seed, zid, eff.zone.tileset, {\n    name: eff.zone.name,\n    objective: { kind: 'none', ...(eff.zone.objectiveLabel ? { label: eff.zone.objectiveLabel } : {}) },\n    noDeeper: true,\n    ...(eff.zone.layoutType ? { layoutType: eff.zone.layoutType } : {}),\n    ...(eff.zone.layoutParams ? { layoutParams: eff.zone.layoutParams } : {}),\n  });\n  sealStageZone(z, eff.zone);\n  w.caveMap[zid] = z;\n  w.scene = {\n    def: eff, zoneId: zid, stageIx: 0, stageT: 0, begun: false, state: {},\n    fell: false, casts: 0, bar: null, prompt: null, barAt: 'top',\n    focus: null, mark: null, hudVeil: false, panelSeal: null, card: null, cardAck: false,\n    fadeTarget: 1, fallBeat: false, landed: false, eventKey: `scene:${id}`,\n  };\n  // Born under black — the first card owns the reveal.\n  w.screenFade = 1;\n  // The off-graph entry: the way home is the return anchor, exactly the\n  // sidezone idiom — a save written mid-scene resolves the player spot to\n  // this surface anchor, so a quit resumes at the ordinary wake for free.\n  w.caveReturn = { zoneId: parent.id, pos: vec(w.player.pos.x, w.player.pos.y), entryFrom: null };\n  w.loadZone(zid, parent.id);\n  // THE EMPTY-FIELD LAW: scripted ground opens with NOBODY on it. Whatever\n  // a tileset's dress rows may mint as actors (a lea's gem cache, a den's\n  // sleeper), the scene owns every body on its stage — only the party\n  // remains, and every later arrival is a scene spawn by construction.\n  for (let i = w.actors.length - 1; i >= 0; i--) {\n    if (w.actors[i].team !== 'player') w.actors.splice(i, 1);\n  }\n  // THE FAR-FIELD DRESS: a boundless stage learns its own heart's palette\n  // so the streamer can keep the country coming past the minted rim.\n  if (eff.zone.boundless) w.scene.dress = buildSceneDress(w, z);\n  if (eff.zone.road) w.scene.road = beginSceneRoad(w, eff.zone.road);\n  if (eff.zone.skyCycle !== undefined) w.scene.skyTime = eff.zone.skyCycle * DAY_LENGTH;\n  return true;\n}\n\n/** Scripted ground is sealed, silent, and rewardless: no spoils mints, no\n *  ambient packs or events, no way out on foot (entry falls back to zone\n *  center; the script alone decides when you leave), no secrets asking to\n *  be found mid-cinematic. The mint's caveDepth already shelters the sky\n *  and bars every world event. */\nfunction sealStageZone(z: ZoneDef, zone: SceneZoneSpec): void {\n  z.level = zone.level;\n  z.spoils = 'none';\n  z.packDensity = 0;\n  z.cohort = 'authored';\n  z.packs = { count: [0, 0], size: [0, 0], table: [] };\n  z.exits = [];\n  if (zone.boundless) z.boundless = true;\n  if (zone.castSeal) z.castSeal = zone.castSeal; // THE CAST SEAL — the stage spec's cast law stamps the ground\n  if (zone.theme) z.theme = { ...z.theme, ...zone.theme };\n  delete z.hollows;\n  delete z.puzzles;\n  delete z.scenery;\n}\n\n// ----------------------------------------------- the far-field dress stream --\n\n/** THE FAR-FIELD PALETTE: sample the minted heart's own standing dress —\n *  plain bodies, carpets and scatter only. State-carriers and law-bearing\n *  kinds never stream: seed-paired mouths (the caveSeeds zip would shear),\n *  doors/wells/hollow seams (state), effect-carriers and hazard ground (a\n *  streamed trap is an ambush nobody authored), pit-fallers, spans,\n *  clearway discs (a road to nowhere), structure surfaces, and portal-clear\n *  keepers. Density is the heart's own per kind, thinned by the dial — the\n *  far field reads as the same country's shoulders, never a second heart. */\nfunction buildSceneDress(w: NativeSceneDirectorHost, z: ZoneDef): SceneDressState | undefined {\n  const cfg = SCENE_CFG.dressStream;\n  const skip = new Set<string>(cfg.skipKinds);\n  const rows = new Map<string, { n: number; rMin: number; rMax: number; rot: boolean }>();\n  for (const d of w.doodads) {\n    if (d.door || d.well || d.hollow || d.effect || d.keep || d.label || d.fall || d.hitbox) continue;\n    if (skip.has(d.kind)) continue;\n    const rule = doodadRuleOf(d.kind);\n    if (rule.seedPaired || rule.clearway || rule.spans || rule.effect\n      || rule.hazardGround || rule.fall || rule.surface) continue;\n    const e = rows.get(d.kind) ?? { n: 0, rMin: d.radius, rMax: d.radius, rot: false };\n    e.n++;\n    e.rMin = Math.min(e.rMin, d.radius);\n    e.rMax = Math.max(e.rMax, d.radius);\n    if (d.rot !== undefined) e.rot = true;\n    rows.set(d.kind, e);\n  }\n  const heartArea = Math.max(1, z.size.w * z.size.h);\n  const palette = [...rows.entries()].map(([kind, e]) => ({\n    kind: kind as Doodad['kind'], rMin: e.rMin, rMax: e.rMax, rot: e.rot,\n    perChunk: (e.n / heartArea) * cfg.chunk * cfg.chunk * cfg.thin,\n  })).filter(p => p.perChunk > 0.02);\n  return palette.length\n    ? { palette, chunks: new Map(), heart: { w: z.size.w, h: z.size.h } }\n    : undefined;\n}\n\n/** One chunk's pieces — a PURE function of (stage seed, chunk coords), so a\n *  culled chunk re-mints byte-identically when the walker returns. Spacing\n *  respects each kind's own rule against this chunk's earlier pieces (no\n *  retries: a refused roll just thins the field). */\nfunction seedDressChunk(sc: SceneRuntime, cx: number, cy: number): Doodad[] {\n  const ds = sc.dress!;\n  const cfg = SCENE_CFG.dressStream;\n  const salt = (Math.imul(cx, 0x9e3779b1) ^ Math.imul(cy, 0x85ebca6b) ^ sc.def.zone.seed) >>> 0;\n  const rng = new Rng(salt);\n  const pieces: Doodad[] = [];\n  for (const row of ds.palette) {\n    let n = Math.floor(row.perChunk);\n    if (rng.next() < row.perChunk - n) n++;\n    for (let i = 0; i < n && pieces.length < cfg.maxPerChunk; i++) {\n      const pos = vec((cx + rng.next()) * cfg.chunk, (cy + rng.next()) * cfg.chunk);\n      const radius = rng.range(row.rMin, row.rMax);\n      const gap = (doodadRuleOf(row.kind).spacing ?? 0) + radius;\n      if (pieces.some(q => Math.hypot(q.pos.x - pos.x, q.pos.y - pos.y) < gap + q.radius)) continue;\n      const d: Doodad = { pos, radius, kind: row.kind };\n      if (sc.road && !sceneRoadShoulder(sc.road, d)) continue;\n      if (row.rot) d.rot = rng.range(-0.4, 0.4);\n      pieces.push(d);\n    }\n  }\n  return pieces;\n}\n\n/** THE FAR-FIELD DRESS STREAMER: keep seeded dress chunks alive around\n *  every seat on a boundless stage. Chunks inside the authored heart mark\n *  seeded-and-blank (generation already dressed them); fresh chunks seed\n *  only past the off-screen gap, and chunks far behind every seat drop\n *  losslessly (same salt → same pieces on return). Scene ground is\n *  local-by-construction (the prologue predates any remote wire; couch\n *  seats share this World and see the same doodads). */\nfunction streamSceneDress(w: NativeSceneDirectorHost, sc: SceneRuntime): void {\n  const ds = sc.dress;\n  if (!ds) return;\n  const cfg = SCENE_CFG.dressStream;\n  const seats = w.seats.map(s => s.actor.pos);\n  if (!seats.length) return;\n  let changed = false;\n  for (const p of seats) {\n    const cx0 = Math.floor((p.x - cfg.reach) / cfg.chunk), cx1 = Math.floor((p.x + cfg.reach) / cfg.chunk);\n    const cy0 = Math.floor((p.y - cfg.reach) / cfg.chunk), cy1 = Math.floor((p.y + cfg.reach) / cfg.chunk);\n    for (let cy = cy0; cy <= cy1; cy++) {\n      for (let cx = cx0; cx <= cx1; cx++) {\n        const key = `${cx},${cy}`;\n        if (ds.chunks.has(key)) continue;\n        const midX = (cx + 0.5) * cfg.chunk, midY = (cy + 0.5) * cfg.chunk;\n        // The heart's footprint is already dressed — mark and move on.\n        if (midX > -cfg.chunk && midX < ds.heart.w + cfg.chunk\n          && midY > -cfg.chunk && midY < ds.heart.h + cfg.chunk) {\n          ds.chunks.set(key, []);\n          continue;\n        }\n        // Fresh terrain lands off-screen, never at the feet.\n        if (seats.some(s => Math.hypot(s.x - midX, s.y - midY) < cfg.seedAhead)) continue;\n        const pieces = seedDressChunk(sc, cx, cy);\n        ds.chunks.set(key, pieces);\n        if (pieces.length) {\n          w.doodads.push(...pieces);\n          changed = true;\n        }\n      }\n    }\n  }\n  for (const [key, pieces] of ds.chunks) {\n    const [cx, cy] = key.split(',').map(Number);\n    const midX = (cx + 0.5) * cfg.chunk, midY = (cy + 0.5) * cfg.chunk;\n    if (seats.some(s => Math.hypot(s.x - midX, s.y - midY) < cfg.cull)) continue;\n    ds.chunks.delete(key);\n    if (pieces.length) {\n      const drop = new Set(pieces);\n      w.doodads = w.doodads.filter(d => !drop.has(d));\n      changed = true;\n    }\n  }\n  if (changed) w.markDoodadsChanged();\n}\n\n// ------------------------------------------------------------- the driver --\n\n/** The director tick — hooked in World.update on RAW dt, BEFORE the\n *  timeflow gate's early return (scenes own their holds and must breathe\n *  through them). Yields only to the true pause (a 'menu' hold). */\nexport function updateScene(w: NativeSceneDirectorHost, dt: number): void {\n  const sc = w.scene;\n  if (!sc) return;\n  if (w.timeflow.heldBy('menu')) return;\n  // The one screen-fade owner while a scene runs (no real death can occur\n  // under the covenant, so the mode-respawn fader stays quiet by construction).\n  // Clamped [0,1] outright: a hostile dt (a rewound timer, a QA harness's\n  // synthetic clock meeting a live rAF) must never ramp the dark past full.\n  w.screenFade = Math.max(0, Math.min(1, sc.fadeTarget > w.screenFade\n    ? Math.min(sc.fadeTarget, w.screenFade + SCENE_CFG.fade.up * dt)\n    : Math.max(sc.fadeTarget, w.screenFade - SCENE_CFG.fade.down * dt)));\n  // The far-field dress rides every director tick while the party stands\n  // on the stage (cheap: a handful of map lookups once the ring is seeded).\n  if (w.zone.id === sc.zoneId) {\n    streamSceneDress(w, sc);\n    if (sc.road) streamSceneRoad(w, sc.road);\n  }\n  const spec = sc.def.stages[sc.stageIx];\n  if (!spec) { endScene(w, sc); return; }\n  const h = STAGES[spec.kind];\n  if (!h) {\n    console.warn(`[scenes] '${sc.def.id}' stage ${sc.stageIx}: unregistered kind '${spec.kind}' — skipped`);\n    sc.stageIx++;\n    sc.begun = false;\n    return;\n  }\n  if (!sc.begun) {\n    sc.begun = true;\n    sc.stageT = 0;\n    sc.state = {};\n    sc.state.skyFrom = sc.skyTime ?? w.time;\n    h.begin?.(w, sc, spec);\n  }\n  sc.stageT += dt;\n  if (spec.sky && w.zone.id === sc.zoneId) {\n    const t = Math.min(1, sc.stageT / Math.max(0.001, spec.sky.transitionSec));\n    const k = t * t * (3 - 2 * t);\n    const from = sc.state.skyFrom as number;\n    sc.skyTime = from + (spec.sky.cycle * DAY_LENGTH - from) * k;\n  }\n  if (h.update(w, sc, spec, dt)) {\n    sc.stageIx++;\n    sc.begun = false;\n    sc.bar = sc.def.stages[sc.stageIx]?.kind === 'reckoning' ? sc.interruptedObjective ?? null : null;\n    sc.prompt = null;\n    sc.mark = null;\n    sc.hudVeil = false;\n    sc.panelSeal = null;\n    sc.landed = false;\n  }\n}\n\n/** Stage list exhausted (the 'home' stage normally tears down; this is the\n *  belt under it). */\nfunction endScene(w: NativeSceneDirectorHost, sc: SceneRuntime): void {\n  w.timeflow.release(SCENE_CFG.holdId);\n  sc.focus = null;\n  w.scene = null;\n}\n\n// -------------------------------------------------------------- the hooks --\n\n/** THE COVENANT — called at the head of World.onPlayerDown: a player seat's\n *  lethal blow on scripted ground FELLS instead of kills. Returns true when\n *  the scene claimed the fall (the caller stops — no wipe, no mode respawn).\n *\n *  THE BODILY FALL (her ruling 2026-09-01): the seat goes DOWN through the\n *  world's own downed state — exactly onPlayerDown's co-op shape — so the\n *  fall reads as a death from its first frame (inputs refused, regeneration\n *  refused, life at zero). While another seat still stands (couch), that is\n *  the whole story: the ordinary revive law may raise them and the scene\n *  plays on. Once NO seat stands, the field is felled (fellSeats) and the\n *  script answers per stage: a stage that PLAYS the fall keeps it (the\n *  reckoning — the Father finishes the horn over the bodies); otherwise the\n *  fall LANDS on the nearest 'land' stage downstream (the wake card) after\n *  a funeral beat — every stage between is skipped, so a death before the\n *  Father is met never summons him: he is the wall you reach alive, and a\n *  player who fell to the tide got everything the road had to teach. A\n *  scene with no landing keeps the old guard (stood up, invulnerable) —\n *  never a stranded party. */\nexport function sceneInterceptFall(w: {scene:World[\"scene\"];seats:readonly Seat[]}, a: Actor): boolean {\n  const sc = w.scene;\n  if (!sc) return false;\n  a.dead = false;\n  a.downed = true;\n  a.life = 0;\n  a.casting = null;\n  a.dash = null;\n  const allyUp = w.seats.some(s => s.actor !== a && !s.actor.dead && !s.actor.downed);\n  if (allyUp) return true;\n  const cur = STAGES[sc.def.stages[sc.stageIx]?.kind ?? ''];\n  if (cur?.onFell === 'play' || cur?.onFell === 'land') { fellSeats(w, sc); return true; }\n  for (let i = sc.stageIx + 1; i < sc.def.stages.length; i++) {\n    if (STAGES[sc.def.stages[i]?.kind ?? '']?.onFell !== 'land') continue;\n    fellSeats(w, sc);\n    sc.stageIx = i;\n    sc.begun = false;\n    sc.bar = null;\n    sc.prompt = null;\n    sc.mark = null;\n    sc.focus = null;\n    sc.hudVeil = false;\n    sc.panelSeal = null;\n    sc.fallBeat = true;\n    sc.landed = true;\n    return true;\n  }\n  // No landing anywhere downstream: the old guard — stood up, guarded, the\n  // scene walks on (a downed party with nowhere to wake would be stranded).\n  a.downed = false;\n  a.life = 1;\n  a.invulnerable = true;\n  a.untargetable = true;\n  sc.fell = true;\n  return true;\n}\n\n/** One seat-pressed cast landed (World.applyInputs) — the drill counts them. */\nexport function sceneNoteCast(w: NativeSceneDirectorHost): void {\n  if (w.scene) w.scene.casts++;\n}\n\n/** The DOM layer's card continue (probes call it directly — the engine\n *  never requires a DOM to finish a scene). */\nexport function sceneCardAck(w: NativeSceneDirectorHost): void {\n  const sc = w.scene;\n  if (sc?.card) sc.cardAck = true;\n}\n\n// ---------------------------------------------------------- spawn plumbing --\n\n/** One scene body: ringed off the hero, already hunting (the wave-frenzy\n *  overlay), and REWARDLESS — noBounty seals xp/loot/gems/orbs whole, the\n *  eventKey scopes it to the scene. */\nfunction spawnSceneBody(w: NativeSceneDirectorHost, sc: SceneRuntime, defId: string, level: number): Actor {\n  const m = w.createMonster(defId, level, 'enemy');\n  const at = w.swarmEntryPoint(w.player.pos, SCENE_CFG.entryBand);\n  m.pos = w.clampPos(vec(at.x + rand(-30, 30), at.y + rand(-30, 30)), m.radius);\n  if (WAVE_CFG.frenzy) w.applyWaveFrenzy(m, WAVE_CFG.frenzy);\n  m.noBounty = true;\n  m.eventKey = sc.eventKey;\n  w.actors.push(m);\n  return m;\n}\n\nfunction pourRows(w: NativeSceneDirectorHost, sc: SceneRuntime, rows: SceneSpawnRow[], ids: number[]): void {\n  for (const r of rows) {\n    for (let i = 0; i < r.count; i++) {\n      ids.push(spawnSceneBody(w, sc, r.def, r.level ?? w.zone.level).id);\n    }\n  }\n}\n\nfunction aliveOf(w: NativeSceneDirectorHost, ids: number[]): number {\n  let n = 0;\n  for (const a of w.actors) if (!a.dead && ids.includes(a.id)) n++;\n  return n;\n}\n\n/** THE FELLED FIELD (her pass 2026-08-31): a scene death is BODILY. The old\n *  guard alone left a \"dead\" hero walking, casting, and visibly\n *  regenerating under the sinking dark — an un-death — and a runner past\n *  the nova's rim was never touched at all. Every seat goes DOWN through\n *  the world's own downed state, so the whole lock arrives from standing\n *  law: applyInputs refuses the seat, regeneration refuses the body,\n *  kill() can't re-enter the death path, and no ally stands to revive.\n *  Life reads honest zero, the guards keep whatever still mills around\n *  off the bodies, and a blast's own knockback still rides out (the hurl\n *  IS the death read). Called by the covenant the moment no seat stands\n *  and by the reckoning's blast (idempotent). The 'mu' and 'home' stages\n *  stand the slain back up by hand — \"nobody truly dies\" is intact. */\nfunction fellSeats(w: {seats:readonly Seat[]}, sc: SceneRuntime): void {\n  for (const seat of w.seats) {\n    const a = seat.actor;\n    if (a.dead) continue;\n    a.downed = true;\n    a.life = 0;\n    a.casting = null;\n    a.dash = null; // willed motion ends; the blast's own hurl (push) rides out\n    a.invulnerable = true;\n    a.untargetable = true;\n  }\n  sc.fell = true;\n}\n\n/** THE ENRAGE's surge: compress the commander's live muster to its last\n *  breaths (the bar visibly leaps — the whole tell IS the show). */\nfunction surgeCast(col: Actor, s: SceneReckoningStage): void {\n  const c = col.casting;\n  if (!c || c.inst.def.id !== s.verb) return;\n  const left = Math.max(0.2, s.enrageLeftSec ?? 1.2);\n  c.elapsed = Math.max(c.elapsed, c.total - left);\n}\n\n// -------------------------------------------------------------- core kinds --\n\nregisterSceneStage('card', {\n  onFell: 'land',\n  begin(w, sc) {\n    // THE FUNERAL BEAT: a fall that just landed here keeps the world in view\n    // over the body for a breath before the dark is allowed to rise.\n    sc.fadeTarget = sc.fallBeat ? 0 : 1;\n    sc.bar = null;\n    sc.prompt = null;\n  },\n  update(w, sc, spec) {\n    const s = spec as SceneCardStage;\n    if (sc.fallBeat) {\n      if (sc.stageT < SCENE_CFG.fallWaitSec) return false;\n      sc.fallBeat = false;\n      sc.fadeTarget = 1;\n    }\n    if (w.screenFade < 0.995) return false; // the dark arrives first\n    if (!sc.card) {\n      // A landing card may speak to the early fall (the Father never met).\n      sc.card = sc.landed && s.fallCard ? s.fallCard : s.card;\n      sc.cardAck = false;\n      // The whole sim holds under the card — a story page, not a pause menu.\n      w.timeflow.hold({ id: SCENE_CFG.holdId, scale: 0, kind: 'cinematic' });\n    }\n    if (!sc.cardAck) return false;\n    sc.card = null;\n    return true;\n  },\n});\n\nregisterSceneStage('drill', {\n  onFell: 'skip',\n  begin(w, sc, spec) {\n    w.timeflow.release(SCENE_CFG.holdId);\n    sc.fadeTarget = 0;\n    sc.barAt = (spec as SceneDrillStage).hud ?? 'hero';\n    sc.state.goalIx = 0;\n    sc.state.acc = 0;\n    sc.state.castBase = sc.casts;\n    sc.state.last = vec(w.player.pos.x, w.player.pos.y);\n  },\n  update(w, sc, spec, _dt) {\n    const s = spec as SceneDrillStage;\n    const st = sc.state as { goalIx: number; acc: number; castBase: number; last: Vec2 };\n    // Footwork accrues on the hero's own displacement (jitter-floored) —\n    // no input hook needed, the body's truth is the count.\n    const p = w.player.pos;\n    const step = dist(p, st.last);\n    if (step > SCENE_CFG.moveEpsilon) st.acc += step;\n    st.last = vec(p.x, p.y);\n    let goal = s.goals[st.goalIx];\n    let frac = 0;\n    while (goal) {\n      frac = goal.kind === 'move'\n        ? Math.min(1, st.acc / goal.amount)\n        : Math.min(1, (sc.casts - st.castBase) / goal.amount);\n      if (frac < 1) break;\n      st.goalIx++;\n      st.acc = 0;\n      st.castBase = sc.casts;\n      st.last = vec(p.x, p.y);\n      goal = s.goals[st.goalIx];\n      frac = 0;\n    }\n    sc.bar = { label: s.label, frac: Math.min(1, (st.goalIx + frac) / Math.max(1, s.goals.length)) };\n    sc.prompt = goal?.prompt ?? null;\n    return st.goalIx >= s.goals.length;\n  },\n});\n\nregisterSceneStage('clash', {\n  onFell: 'skip',\n  begin(w, sc, spec) {\n    const s = spec as SceneClashStage;\n    sc.barAt = s.hud ?? 'hero';\n    const ids: number[] = [];\n    pourRows(w, sc, s.spawns, ids);\n    sc.state.ids = ids;\n    sc.state.clearedAt = null;\n    if (s.announce) {\n      w.text(vec(w.player.pos.x, w.player.pos.y - 60), s.announce, s.announceColor ?? '#c8b070', 14);\n    }\n  },\n  update(w, sc, spec) {\n    const s = spec as SceneClashStage;\n    const st = sc.state as { ids: number[]; clearedAt: number | null };\n    const alive = aliveOf(w, st.ids);\n    if (s.label) {\n      sc.bar = { label: s.label, frac: st.ids.length ? (st.ids.length - alive) / st.ids.length : 1 };\n    }\n    if (alive === 0 && st.clearedAt === null) st.clearedAt = sc.stageT;\n    return st.clearedAt !== null && sc.stageT - st.clearedAt >= s.pauseSec;\n  },\n});\n\nregisterSceneStage('assault', {\n  onFell: 'skip',\n  begin(w, sc, spec) {\n    sc.barAt = (spec as SceneAssaultStage).hud ?? 'top';\n    sc.state.next = 0;\n    sc.state.lastPour = 0;\n    sc.state.ids = [];\n    sc.state.distance = 0;\n    sc.state.last = vec(w.player.pos.x, w.player.pos.y);\n    sc.state.farthest = sc.road ? sceneRoadCoordinates(sc.road, w.player.pos).along : 0;\n    sc.interruptedObjective = undefined;\n  },\n  update(w, sc, spec) {\n    const s = spec as SceneAssaultStage;\n    const st = sc.state as { next: number; lastPour: number; ids: number[];\n      distance: number; farthest: number; last: Vec2 };\n    while (st.next < s.rows.length && sc.stageT >= s.rows[st.next].at) {\n      const row = s.rows[st.next];\n      pourRows(w, sc, row.spawns, st.ids);\n      if (row.announce) {\n        w.text(vec(w.player.pos.x, w.player.pos.y - 60), row.announce, row.announceColor ?? '#c8b070', 14);\n      }\n      st.lastPour = sc.stageT;\n      st.next++;\n    }\n    // Past the script's tail, the last row REPOURS on its cadence — the\n    // tide that never ebbs (the whole point of this road).\n    const every = s.repeatLastEvery ?? 0;\n    if (every > 0 && s.rows.length > 0 && st.next >= s.rows.length && sc.stageT - st.lastPour >= every) {\n      pourRows(w, sc, s.rows[s.rows.length - 1].spawns, st.ids);\n      st.lastPour = sc.stageT;\n    }\n    if (s.objective) {\n      const goal = s.objective;\n      if (goal.progress.kind === 'road' && sc.road) {\n        const p = w.player;\n        const along = sceneRoadCoordinates(sc.road, p.pos).along;\n        // Credit only new forward ground traversed ON the way by this hero.\n        // Backtracking and off-road shortcuts cannot be farmed by re-entry.\n        if (!p.dead && !p.downed && !p.push && onSceneRoad(sc.road, st.last) && onSceneRoad(sc.road, p.pos)) {\n          st.distance += Math.max(0, along - st.farthest);\n        }\n        st.farthest = Math.max(st.farthest, along);\n        st.last = vec(p.pos.x, p.pos.y);\n      }\n      const amount = goal.progress.kind === 'road' ? st.distance : sc.stageT;\n      // The cap also guards giant dt/displacements and misconfigured data.\n      const interruptAt = Math.max(0.01, Math.min(0.99, goal.interruptAt));\n      const frac = Math.min(interruptAt, amount / Math.max(1, goal.progress.amount));\n      sc.bar = { label: goal.label, frac };\n      sc.prompt = goal.prompt;\n      if (frac >= interruptAt || sc.stageT >= s.surviveSec) {\n        sc.interruptedObjective = { ...sc.bar };\n        return true;\n      }\n      return false;\n    }\n    if (s.label) sc.bar = { label: s.label, frac: Math.min(1, sc.stageT / s.surviveSec) };\n    return sc.stageT >= s.surviveSec;\n  },\n});\n\nregisterSceneStage('reckoning', {\n  onFell: 'play',\n  begin(w, sc, spec) {\n    const s = spec as SceneReckoningStage;\n    // THE AGENCY BEAT: the commander arrives just past the screen's edge —\n    // rewardless like every scene body, posted so it holds its ground — and\n    // the world is NEVER held (release whatever a prior beat left standing:\n    // the stage is self-sufficient wherever the fall fast-forwards from).\n    w.timeflow.release(SCENE_CFG.holdId);\n    const col = w.createMonster(s.def, s.level, 'enemy');\n    const at = w.swarmEntryPoint(w.player.pos, [s.spawnDist, s.spawnDist + 60]);\n    col.pos = w.clampPos(vec(at.x, at.y), col.radius);\n    col.noBounty = true;\n    col.eventKey = sc.eventKey;\n    col.aiPost = vec(col.pos.x, col.pos.y);\n    // THE MUSTER STANDS ALONE: the whole kit is banned from the AI picker —\n    // the commander freelances nothing while the director owns the beat (a\n    // direct useSkill never reads the bans, so the ordered verb still flies).\n    for (const inst of col.skills) if (inst) (col.aiSkillBans ??= new Set()).add(inst.def.id);\n    w.actors.push(col);\n    w.text(vec(col.pos.x, col.pos.y - col.radius - 26), col.name, s.announceColor ?? '#e8c87a', 17);\n    if (s.announce) {\n      w.text(vec(w.player.pos.x, w.player.pos.y - 60), s.announce, s.announceColor ?? '#c8b070', 14);\n    }\n    // Nobody arrives here felled any more: a fall upstream LANDS on the wake\n    // (the covenant's landing law) — the Father is met alive or not at all.\n    sc.mark = { id: col.id, color: col.color };\n    sc.focus = null; // the agency beat owns no camera — the eye walks only for the fire-off\n    sc.state.colId = col.id;\n    sc.state.cast = false;\n    sc.state.blastAt = null;\n    sc.bar = sc.interruptedObjective ?? null;\n    sc.barAt = 'top';\n    sc.prompt = null;\n  },\n  update(w, sc, spec, dt) {\n    const s = spec as SceneReckoningStage;\n    const st = sc.state as {\n      colId: number; cast: boolean; blastAt: number | null;\n      enraged?: boolean; everOrdered?: boolean; panT?: number; flared?: boolean;\n      surged?: boolean;\n    };\n    const col = w.actors.find(a => a.id === st.colId);\n    // THE DEAD-COMMANDER LANE (the mechanics-breaker's net): a Father who is\n    // somehow truly finished just fades the stage forward — the wake and Mu\n    // follow as ever. Never an immunity, never a lock, never a refusal print.\n    if (!col || col.dead) {\n      // Even a mechanics-breaker cannot turn the unfinished journey into a\n      // living exit. Keep the existing mortal commander and Mu safety net.\n      fellSeats(w, sc);\n      sc.mark = null; sc.focus = null; sc.fadeTarget = 1;\n      return w.screenFade >= 0.995;\n    }\n    // THE FIELD-FALL SURGE (her ruling 2026-09-01): the tide may fell the\n    // whole party while the Father still musters — the covenant lays them\n    // bodily down in place (this stage PLAYS the fall) and he has nothing\n    // left to wait for: the live muster surges to its last breaths, the\n    // witness walks the eye out over the bodies, and the horn still ends\n    // the road on screen. A muster ordered over a felled field opens\n    // surged (below), so the beat stays tight either way.\n    const fieldDown = !w.seats.some(s => !s.actor.dead && !s.actor.downed);\n    if (fieldDown && st.blastAt === null && !st.surged && col.casting) {\n      st.surged = true;\n      surgeCast(col, s);\n    }\n    // THE ENRAGE (show, never tell): bled below the floor, the Father does\n    // not shrug — he HURRIES. A visible fury takes him (the rally his own\n    // voice-part preaches, turned inward), the ground kicks, and the cast\n    // bar SURGES to its last breaths. He stays honestly mortal throughout;\n    // the surge simply makes finishing him a race nobody was meant to win.\n    if (s.floorFrac > 0 && !st.enraged && col.life <= col.maxLife() * s.floorFrac) {\n      st.enraged = true;\n      col.applyStatus('rally', 0, 3, 'the last breath');\n      w.shake = Math.max(w.shake, SCENE_CFG.blastShake * 0.5);\n      surgeCast(col, s);\n    }\n    // Order the verb after the grace beat — a fresh instance every time,\n    // and THE CLOCK YIELDS TO THE DIRECTOR: cooldowns live ACTOR-side by\n    // def id (Actor.cooldowns), so whatever stamped the verb's clock — a\n    // press that slipped in before the ban bound, a completed earlier\n    // muster — is cleared before the order; no clock can refuse the beat.\n    // A refusal (mid-recovery, a stun landing the same tick) retries next\n    // tick.\n    if (!st.cast && sc.stageT >= s.graceSec && !col.isStunned() && !col.heldBy) {\n      col.cooldowns.delete(s.verb);\n      col.cooldownTotals.delete(s.verb);\n      if (col.casting && col.casting.inst.def.id !== s.verb) col.casting = null;\n      const inst = SKILLS[s.verb] ? makeSkillInstance(SKILLS[s.verb], 1) : null;\n      if (!inst) {\n        console.warn(`[scenes] reckoning verb '${s.verb}' is not a registered skill`);\n        st.cast = true;\n        st.blastAt = sc.stageT;\n        fellSeats(w, sc); // the degrade lane inherits the end — the card still narrates a fall\n      } else if (w.useSkill(col, inst, vec(col.pos.x, col.pos.y))) {\n        st.cast = true;\n        st.everOrdered = true;\n        // A muster ordered mid-fury — or over a felled field — opens already\n        // surged: the enrage survives interrupts (delay stays real, the race\n        // stays lost), and a dead field is never made to wait ten breaths.\n        if (st.enraged || fieldDown) surgeCast(col, s);\n      }\n    }\n    // THE PATIENCE BELT (QA: the stage must NEVER strand the tutorial): a\n    // muster that has NEVER been ordered well past its grace — some lane\n    // the clears above don't cover — degrades exactly like the missing-verb\n    // lane: fade forward to the wake. Better a skipped blast than a\n    // stranded player beating on an inert Father. Gated on everOrdered:\n    // once one muster has genuinely opened, interrupts and re-arms are the\n    // machinery WORKING — the belt must never race a live re-arm.\n    if (!st.cast && !st.everOrdered && sc.stageT >= s.graceSec + SCENE_CFG.musterPatienceSec) {\n      console.warn(`[scenes] reckoning verb '${s.verb}' refused past patience — degrading to the fade`);\n      st.cast = true;\n      st.blastAt = sc.stageT;\n      fellSeats(w, sc);\n    }\n    if (st.cast && st.blastAt === null && !col.casting) {\n      if (col.isStunned() || col.heldBy != null) {\n        // Interrupted — the player's honest little victory. Delay is real;\n        // denial is not: the muster re-arms the moment the body is free\n        // (and the next muster's tail flares + pans afresh).\n        st.cast = false;\n        st.flared = false;\n      } else {\n        // The verb has resolved — the field is felled. The nova already\n        // caught everyone it reached at the one death chokepoint (the\n        // covenant's guard); the sweep makes the end BODILY for every seat\n        // — the runner past its rim included. The horde it spent honestly.\n        st.blastAt = sc.stageT;\n        sc.mark = null;\n        w.shake = Math.max(w.shake, SCENE_CFG.blastShake);\n        fellSeats(w, sc);\n      }\n    }\n    if (st.blastAt !== null && sc.stageT - st.blastAt >= s.blastWaitSec) {\n      sc.fadeTarget = 1;\n      if (w.screenFade >= 0.995) { sc.focus = null; return true; }\n    }\n    // THE WITNESS (her pass 2026-08-31): the fire-off is ALWAYS seen —\n    // however far the road has carried the player, the eye walks to the\n    // Father for the muster's last breaths, watches the horn fire, holds\n    // through the detonation, then comes home to the fallen body for the\n    // dark. The renderer SNAPS to sc.focus (drawn == scripted, no easing\n    // forked there), so the director walks the point itself: smoothstep\n    // out over travelSec, home at the backSec pace. An interrupt mid-pan\n    // walks the eye back the same way — the muster re-arms, and agency\n    // keeps its camera until the next tail.\n    {\n      const fp = SCENE_CFG.firePan;\n      const castLeft = col.casting && col.casting.inst.def.id === s.verb\n        ? col.casting.total - col.casting.elapsed : null;\n      const eyeOut = st.blastAt !== null\n        ? sc.stageT - st.blastAt < fp.dwellSec\n        : castLeft !== null && castLeft <= fp.leadSec;\n      // THE FLARE: the pan's first beat is the Father's own wind-up read —\n      // the enrage's fury worn visibly (now guaranteed a witness) and the\n      // ground kicking under him as the bar enters its last breaths.\n      if (eyeOut && st.blastAt === null && !st.flared) {\n        st.flared = true;\n        col.applyStatus('rally', 0, 3, 'the reckoning');\n        w.shake = Math.max(w.shake, SCENE_CFG.blastShake * 0.5);\n      }\n      const step = eyeOut ? dt : -dt * (fp.travelSec / Math.max(0.01, fp.backSec));\n      st.panT = Math.max(0, Math.min(fp.travelSec, (st.panT ?? 0) + step));\n      if (st.panT > 0) {\n        const t = st.panT / fp.travelSec;\n        const k = t * t * (3 - 2 * t); // smoothstep — the fabric's one ease\n        const home = w.player.pos;\n        sc.focus = vec(home.x + (col.pos.x - home.x) * k, home.y + (col.pos.y - home.y) * k);\n      } else if (!eyeOut) {\n        sc.focus = null; // k = 0 IS the hero — the release is seamless by construction\n      }\n    }\n    return false;\n  },\n});\n\nregisterSceneStage('home', {\n  onFell: 'play',\n  begin(w, sc) {\n    // Teardown, whole: release the hold, heal the hero for the wake, walk\n    // the one surface road home (this unwinds the off-graph return state and\n    // discards the staging zone's actors with the zone), and delete the\n    // minted ground so not even the session cache remembers it.\n    w.timeflow.release(SCENE_CFG.holdId);\n    sc.focus = null;\n    const p = w.player;\n    p.invulnerable = false;\n    p.untargetable = false;\n    p.downed = false; // the felled field's exit — a slain hero wakes standing\n    p.life = p.maxLife();\n    p.fillResources();\n    w.loadZone(START_ZONE);\n    delete w.caveMap[sc.zoneId];\n    // COMPLETION is the only stamp that counts: the scene never plays again,\n    // and the RUN begins here — its first save (charDirty → the shell's\n    // prompt persist) is this bedside wake, never a scene beat.\n    if (!(w.account.ledger[sc.def.ledger] ?? 0)) bumpLedger(w.account.ledger, sc.def.ledger);\n    w.accountDirty = true;\n    w.charDirty = true;\n    sc.fadeTarget = 0;\n  },\n  update(w, sc) {\n    if (w.screenFade > 0.005) return false;\n    endScene(w, sc);\n    return false; // endScene nulled the runtime — nothing left to advance\n  },\n});\n\n// ------------------------------------------------------- the mu stage (hub) --\n// THE HUB BETWEEN LIVES (data/mu.ts): the hero stands as a wisp in a zone of\n// nothing; the class roster stands as shaded apparitions in three arcs — the\n// dealt hand AWAKE, known classes outside the hand VEILED, undiscovered ones as\n// faint unknown cowls. A still linger by an awake vessel fills the scene bar\n// and posts a CLASS REQUEST the shell polls (muTakeClassRequest) to open that\n// class's card; taking it builds the run's whole new world outside, so this\n// stage never completes and never restores anything.\n\n/** One standing apparition's live row (per-stage scratch). */\ninterface MuApp {\n  id: number;\n  classId: string | null;\n  rank: 'awake' | 'veiled' | 'faint';\n  /** THE OFFERED CONTRACT (engine/muDeal.ts): the mode id this awake vessel\n   *  stands offered under (null = an ordinary mortal waking). The body wears\n   *  the contract's marker status — the drawn tell; the card reads this. */\n  offer: string | null;\n  /** The commune linger (seconds engaged + still). */\n  t: number;\n  /** Latch: fired (awake) or refused (veiled) — re-arms on step-out. */\n  noted: boolean;\n}\n\ninterface MuState {\n  apps?: MuApp[];\n  classReq?: string | null;\n  /** THE NEAREST LAW: the one vessel engaged this frame (actor id), or null. */\n  engagedId?: number | null;\n  /** THE GLOBE, derived by THE RING LAW (engine/muRing.ts) at the seating —\n   *  the wrap keeps its void beyond the outermost ring at any count. */\n  wrap?: { radius: number; reentry: number };\n}\n\nconst muZoneId = (): string => `scene_${MU_SCENE_ID}`;\n\n/** THE HAND LAW + THE OFFERED CONTRACT — the deal is engine/muDeal.ts's ONE\n *  pure function of the account (seeded off its own history, so a\n *  re-entered Mu keeps its hand and its offers within a sitting); this only\n *  SEATS what it returns: three arcs of bodies, the rank markers, and the\n *  offered vessel's contract status (the drawn tell). */\nfunction muSpawnApparitions(w: NativeSceneDirectorHost, sc: SceneRuntime, st: MuState): MuApp[] {\n  const deal = muDeal(w.account);\n  // THE RING LAW (engine/muRing.ts): where each rank STANDS is derived from\n  // how many stand — a readable seat gap widens the crescent, closes it into\n  // a ring, then grows it; ranks stack outward; the globe's wrap keeps its\n  // void beyond the outermost seat.\n  const rings = muRings({ awake: deal.awake.length, veiled: deal.veiled.length, faint: deal.faintN });\n  st.wrap = rings.wrap;\n  const cx = w.arena.w / 2, cy = w.arena.h / 2;\n  const apps: MuApp[] = [];\n  const seat = (defId: string, classId: string | null, rank: MuApp['rank'],\n    th: number, r: number): void => {\n    const m = w.createMonster(defId, 1, 'player');\n    m.pos = w.clampPos(vec(cx + Math.cos(th) * r, cy + Math.sin(th) * r), m.radius);\n    // THE GAZE: born looking at its mark (the wisp) — never a snap later.\n    m.facing = muGazeAngle(w, m);\n    m.facingPrev = m.facing;\n    m.noBounty = true;\n    m.eventKey = sc.eventKey;\n    if (rank === 'veiled') m.applyStatus('mu_veiled', 0, 1, 'Mu');\n    if (rank === 'faint') m.applyStatus('mu_faint', 0, 1, 'Mu');\n    // THE OFFERED CONTRACT: an awake vessel the deal offered under a\n    // contract wears that contract's marker (ModeOfferSpec.status) — the\n    // red ember the player reads before a word is said.\n    const offer = rank === 'awake' && classId ? deal.offers.get(classId) ?? null : null;\n    const offerStatus = offer ? MODE_BY_ID[offer]?.muOffer?.status : undefined;\n    if (offerStatus) m.applyStatus(offerStatus, 0, 1, 'Mu');\n    w.actors.push(m);\n    apps.push({ id: m.id, classId, rank, offer, t: 0, noted: false }); // offer = the muDeal roll\n  };\n  // THE DEAL's three arcs (engine/muDeal.ts) on THE RING LAW's seats: the\n  // hand, the veiled pool, the cowls — seat order = deal order.\n  deal.awake.forEach((c, i) => seat(apparitionDefId(c.id), c.id, 'awake', rings.awake.angles[i], rings.awake.radius));\n  deal.veiled.forEach((c, i) => seat(apparitionDefId(c.id), c.id, 'veiled', rings.veiled.angles[i], rings.veiled.radius));\n  for (let i = 0; i < deal.faintN; i++) {\n    seat(APPARITION_UNKNOWN_ID, null, 'faint', rings.faint.angles[i], rings.faint.radius);\n  }\n  return apps;\n}\n\n/** THE GAZE (MU_CFG.gaze): the bearing a vessel's eyes hold — toward the\n *  live wisp, the wake point, or due south (screen y grows downward). */\nfunction muGazeAngle(w: NativeSceneDirectorHost, a: { pos: Vec2 }): number {\n  const g = MU_CFG.gaze;\n  if (g.at === 'south') return Math.PI / 2;\n  const t = g.at === 'wisp' ? w.player.pos : vec(w.arena.w / 2, w.arena.h / 2);\n  return Math.atan2(t.y - a.pos.y, t.x - a.pos.x);\n}\n\n/** Swing `from` toward `to` by at most `cap` radians (cap <= 0 = instant). */\nfunction muTurnToward(from: number, to: number, cap: number): number {\n  if (cap <= 0) return to;\n  const d = angleDiff(from, to);\n  return Math.abs(d) <= cap ? to : from + Math.sign(d) * cap;\n}\n\nregisterSceneStage('mu', {\n  onFell: 'play',\n  begin(w, sc, spec) {\n    const s = spec as SceneMuStage;\n    w.timeflow.release(SCENE_CFG.holdId);\n    sc.focus = null;\n    sc.mark = null;\n    sc.hudVeil = true;\n    // THE PANEL SEAL: the hub's listed hero pages stay shut while the wisp\n    // stands (World.panelSealed is the one read the toggles + tray share).\n    sc.panelSeal = MU_CFG.sealPanels.ids.length\n      ? { ids: new Set<string>(MU_CFG.sealPanels.ids), line: MU_CFG.sealPanels.line, ink: MU_CFG.sealPanels.ink } : null;\n    sc.barAt = 'hero';\n    // THE GROUND — two roads in, one place: the standalone hub scene IS this\n    // zone already (sceneBegin minted it); the prologue arrives from its own\n    // staging ground and mints Mu beside it, off-graph like everything else.\n    const zid = muZoneId();\n    if (w.zone.id !== zid) {\n      if (!w.caveMap[zid]) {\n        const z = mintCave(w.zone, MU_ZONE.seed, zid, MU_ZONE.tileset, {\n          name: MU_ZONE.name,\n          objective: { kind: 'none', ...(MU_ZONE.objectiveLabel ? { label: MU_ZONE.objectiveLabel } : {}) },\n          noDeeper: true,\n        });\n        sealStageZone(z, MU_ZONE);\n        w.caveMap[zid] = z;\n      }\n      w.loadZone(zid, w.zone.id);\n      // THE EMPTY-FIELD LAW again at this door — Mu opens with nobody on it.\n      for (let i = w.actors.length - 1; i >= 0; i--) {\n        if (w.actors[i].team !== 'player') w.actors.splice(i, 1);\n      }\n    }\n    // COMPLETION AT THE THRESHOLD (the prologue): the tutorial is LIVED the\n    // moment the spirit arrives — a quit from Mu re-opens Mu on the next\n    // Begin (the shell's veteran lane), never the war again.\n    if (s.stampComplete && !(w.account.ledger[sc.def.ledger] ?? 0)) {\n      bumpLedger(w.account.ledger, sc.def.ledger);\n      w.accountDirty = true;\n    }\n    // THE WISP: a small guarded light between lives — no kit, no vitals to\n    // lose, ethereal ink. Nothing here is ever restored: taking a vessel\n    // builds a whole new world, so the swap is honest by construction.\n    const p = w.player;\n    // Drop the Reliquary's stats and grants at entry, before filling vitals.\n    // recalcPlayer keeps them suppressed for every later rebuild in Mu.\n    p.relicEffectsSuppressed = true;\n    w.recalcPlayer();\n    p.invulnerable = true;\n    p.untargetable = true;\n    p.downed = false; // the felled field's exit — a downed seat eats its own inputs (applyInputs)\n    p.life = p.maxLife();\n    p.fillResources();\n    p.casting = null;\n    p.push = null;\n    p.dash = null;\n    p.look = MU_CFG.wisp.look;\n    p.cosmeticKind = 'wisp';\n    p.color = MU_CFG.wisp.color;\n    p.radius = MU_CFG.wisp.radius;\n    for (let i = 0; i < p.skills.length; i++) p.skills[i] = null;\n    const st = sc.state as MuState;\n    st.apps = muSpawnApparitions(w, sc, st);\n    st.classReq = null;\n    st.engagedId = null;\n    sc.fadeTarget = 0;\n    // The standing instruction is a YOUNG account's line only (her word:\n    // veterans know the drift — keep the stillness for them).\n    sc.prompt = w.account.runRecords.length < MU_CFG.promptRuns ? MU_CFG.prompt : null;\n  },\n  update(w, sc, _spec, dt) {\n    const st = sc.state as MuState;\n    const apps = st.apps ?? [];\n    if (w.zone.id !== muZoneId()) return false;\n    const p = w.player;\n    // THE GLOBE (her word): far enough into the nothing and it WRAPS — the\n    // spirit pops out the antipode still walking the same bearing, so every\n    // long drift leads right back to the vessels. The rim is pure void (the\n    // arcs end well inside it; the motes are screen-space), so the seam is\n    // invisible by construction — the camera just keeps following a light\n    // through nothing.\n    {\n      const cx = w.arena.w / 2, cy = w.arena.h / 2;\n      const dxw = p.pos.x - cx, dyw = p.pos.y - cy;\n      const dw = Math.hypot(dxw, dyw);\n      // THE RING LAW derives the globe: the wrap stands `wrap.clear` past the\n      // outermost seat (muRings), the authored dials its floor.\n      const wrap = st.wrap ?? { radius: MU_CFG.wrap.radius, reentry: MU_CFG.wrap.reentry };\n      if (dw > wrap.radius) {\n        const fromX = p.pos.x, fromY = p.pos.y;\n        const k = wrap.reentry / dw;\n        p.pos.x = cx - dxw * k;\n        p.pos.y = cy - dyw * k;\n        p.push = null;\n        p.dash = null;\n        // THE CONTINUOUS EYE: bank the teleport so the abyss's parallax\n        // strata never see it — the camera jumps, the deep field does not,\n        // and the wrap leaves no residual shift at all (her seam note).\n        w.ambientCamShift.x += p.pos.x - fromX;\n        w.ambientCamShift.y += p.pos.y - fromY;\n      }\n    }\n    // THE YOUNG PROMPT: the standing instruction speaks only while the\n    // account is still learning the drift (few completed runs) — a veteran's\n    // Mu keeps its stillness, and the vessels speak through approach alone.\n    const young = w.account.runRecords.length < MU_CFG.promptRuns;\n    // THE NEAREST LAW (2026-09-13, her word — \"standing adjacent to a class\n    // might read as the ADJACENT class\"): ONE vessel engages at a time — the\n    // nearest by SURFACE distance within the dwell reach, seat order breaking\n    // an exact tie — and every other row stands un-engaged (timer zeroed,\n    // latch re-armed: a step from one vessel toward the next re-arms the\n    // one left behind). THE RING LAW's disjoint reach means the nearest is\n    // normally the ONLY one in reach; this is the belt for a patched gap.\n    // The gaze still turns every vessel, engaged or not.\n    let nearest: { row: MuApp; a: Actor; d: number } | null = null;\n    for (const row of apps) {\n      const a = w.actors.find(x => x.id === row.id);\n      if (!a) continue;\n      // THE GAZE (MU_CFG.gaze): the vessel's eyes follow their mark — the\n      // drifting wisp by default — swinging at turnRate so the turn reads\n      // as attention, never a snap. aims:false bodies wear no tick and no\n      // mind turns them, so this is the one hand on an apparition's facing.\n      a.facing = muTurnToward(a.facing, muGazeAngle(w, a), MU_CFG.gaze.turnRate * dt);\n      const d = dist(p.pos, a.pos) - a.radius; // surface distance\n      if (d <= MU_CFG.dwell.radius && (!nearest || d < nearest.d)) nearest = { row, a, d };\n    }\n    st.engagedId = nearest?.row.id ?? null;\n    for (const row of apps) {\n      if (row === nearest?.row) continue;\n      row.t = 0;\n      row.noted = false; // step-out re-arms the latch (the Dwell law)\n    }\n    sc.bar = null;\n    if (!nearest) {\n      sc.prompt = young ? MU_CFG.prompt : null;\n      return false; // Mu never completes — the pick rebuilds the world outside.\n    }\n    const { row, a } = nearest;\n    if (row.rank === 'faint') {\n      if (young) sc.prompt = MU_CFG.faintLine;\n      return false;\n    }\n    if (row.rank === 'veiled') {\n      const line = row.classId && w.account.pendingClassUnlocks.has(row.classId)\n        ? MU_CFG.pendingLine : MU_CFG.veiledLine;\n      if (!row.noted) {\n        row.noted = true;\n        w.text(vec(a.pos.x, a.pos.y - a.radius - 18), line, '#8a86a0', 12);\n      }\n      if (young) sc.prompt = line;\n      return false;\n    }\n    // AWAKE: the still linger fills the bar, then posts the class request\n    // (consumed until step-out, so a closed card never re-pops in place).\n    sc.prompt = null;\n    if (row.noted) return false;\n    if (!w.playerIdle()) {\n      row.t = 0;\n      return false;\n    }\n    row.t += dt;\n    sc.bar = { label: a.name, frac: Math.min(1, row.t / MU_CFG.dwell.sec) };\n    if (row.t >= MU_CFG.dwell.sec) {\n      row.noted = true;\n      st.classReq = row.classId;\n      sc.bar = null;\n    }\n    return false; // Mu never completes — the pick rebuilds the world outside.\n  },\n});\n\n/** Is the running scene sitting on its Mu stage? (The shell's label/veil\n *  switches read this — one predicate, engine-owned.) */\nexport function muStageLive(w: NativeSceneDirectorHost): boolean {\n  return !!w.scene && w.scene.def.stages[w.scene.stageIx]?.kind === 'mu';\n}\n\n/** Take (and clear) the Mu stage's pending class request — the shell polls\n *  this beside the dwell flags and opens that class's card. */\nexport function muTakeClassRequest(w: NativeSceneDirectorHost): string | null {\n  const sc = w.scene;\n  if (!sc) return null;\n  const st = sc.state as MuState;\n  const r = st.classReq ?? null;\n  if (r) st.classReq = null;\n  return r;\n}\n\n/** THE OFFERED CONTRACT's read (engine/muDeal.ts): the mode id the AWAKE\n *  vessel of `classId` stands offered under this waking, or null for an\n *  ordinary mortal waking. The shell hands it to the card beside the class\n *  request so the card opens pre-sworn; a pure read of the stage's seated\n *  deal — the same row whose marker status the body wears. */\nexport function muOfferOf(w: NativeSceneDirectorHost, classId: string): string | null {\n  const sc = w.scene;\n  if (!sc || !muStageLive(w)) return null;\n  const st = sc.state as MuState;\n  return st.apps?.find(r => r.rank === 'awake' && r.classId === classId)?.offer ?? null;\n}\n\n/** THE NEAREST LAW's read: the ONE vessel the wisp engages this frame (the\n *  nearest surface within the dwell reach), or null — the same row whose\n *  linger fills the bar; HUD, dev lanes and the probe read it here. */\nexport function muEngagedVessel(w: NativeSceneDirectorHost): { id: number; classId: string | null; rank: MuApp['rank']; offer: string | null } | null {\n  const sc = w.scene;\n  if (!sc || !muStageLive(w)) return null;\n  const st = sc.state as MuState;\n  const row = st.engagedId == null ? undefined : st.apps?.find(r => r.id === st.engagedId);\n  return row ? { id: row.id, classId: row.classId, rank: row.rank, offer: row.offer } : null;\n}\n\n// THE MARK — the attention fabric's chevron on whatever body the running\n// scene marks (the agency reckoning's commander). A source, never a draw:\n// the generic edge-pointer pass renders it, and skips it while on-screen.\nregisterAttentionSource((w: NativeSceneDirectorHost) => {\n  const m = w.scene?.mark;\n  if (!m) return [];\n  const a = w.actors.find(x => x.id === m.id);\n  if (!a || a.dead) return [];\n  return [{\n    id: 'scene_mark', pos: { x: a.pos.x, y: a.pos.y },\n    color: m.color, glyph: '☠', label: a.name, z: 3,\n  }];\n});\n","files":[{"file":"src/engine/scenes.ts","before":"004dead86a408145ba1d271bc9931a446473d089644b797366349e8b06683eb7","after":"abf68e944c154a173ebd194544b5f296937b981ad8ccb5b24887031d053a2cdc","edits":[{"before":"import type {NativeSceneDirectorHost} from './nativeSceneDirectorHost';","after":"import type {NativeSceneDirectorHost} from './nativeSceneDirectorHost';\nimport {observeNativeCombatBirth,observeNativeCombatRetirement,finishNativeCombatRetirement,cancelNativeCombatRetirement} from './nativeCombatRecordObservation';"},{"before":"function spawnSceneBody(w: NativeSceneDirectorHost, sc: SceneRuntime, defId: string, level: number): Actor {\n  const m = w.createMonster(defId, level, 'enemy');\n  const at = w.swarmEntryPoint(w.player.pos, SCENE_CFG.entryBand);\n  m.pos = w.clampPos(vec(at.x + rand(-30, 30), at.y + rand(-30, 30)), m.radius);\n  if (WAVE_CFG.frenzy) w.applyWaveFrenzy(m, WAVE_CFG.frenzy);\n  m.noBounty = true;\n  m.eventKey = sc.eventKey;\n  w.actors.push(m);\n  return m;\n}","after":"function spawnSceneBody(w: NativeSceneDirectorHost, sc: SceneRuntime, defId: string, level: number): Actor {\n  return w.nativeSceneBodies ? w.nativeSceneBodies.spawnBody(sc,defId,level) : nativeSceneSpawnBody(w,sc,defId,level);\n}\n\nexport function nativeSceneSpawnBody(w: NativeSceneDirectorHost, sc: SceneRuntime, defId: string, level: number): Actor {\n  const m = w.createMonster(defId, level, 'enemy');\n  const at = w.swarmEntryPoint(w.player.pos, SCENE_CFG.entryBand);\n  m.pos = w.clampPos(vec(at.x + rand(-30, 30), at.y + rand(-30, 30)), m.radius);\n  if (WAVE_CFG.frenzy) w.applyWaveFrenzy(m, WAVE_CFG.frenzy);\n  m.noBounty = true;\n  m.eventKey = sc.eventKey;\n  w.actors.push(m);\n  observeNativeCombatBirth(w,m);\n  return m;\n}"},{"before":"function muSpawnApparitions(w: NativeSceneDirectorHost, sc: SceneRuntime, st: MuState): MuApp[] {\n  const deal = muDeal(w.account);\n  // THE RING LAW (engine/muRing.ts): where each rank STANDS is derived from\n  // how many stand — a readable seat gap widens the crescent, closes it into\n  // a ring, then grows it; ranks stack outward; the globe's wrap keeps its\n  // void beyond the outermost seat.\n  const rings = muRings({ awake: deal.awake.length, veiled: deal.veiled.length, faint: deal.faintN });\n  st.wrap = rings.wrap;\n  const cx = w.arena.w / 2, cy = w.arena.h / 2;\n  const apps: MuApp[] = [];\n  const seat = (defId: string, classId: string | null, rank: MuApp['rank'],\n    th: number, r: number): void => {\n    const m = w.createMonster(defId, 1, 'player');\n    m.pos = w.clampPos(vec(cx + Math.cos(th) * r, cy + Math.sin(th) * r), m.radius);\n    // THE GAZE: born looking at its mark (the wisp) — never a snap later.\n    m.facing = muGazeAngle(w, m);\n    m.facingPrev = m.facing;\n    m.noBounty = true;\n    m.eventKey = sc.eventKey;\n    if (rank === 'veiled') m.applyStatus('mu_veiled', 0, 1, 'Mu');\n    if (rank === 'faint') m.applyStatus('mu_faint', 0, 1, 'Mu');\n    // THE OFFERED CONTRACT: an awake vessel the deal offered under a\n    // contract wears that contract's marker (ModeOfferSpec.status) — the\n    // red ember the player reads before a word is said.\n    const offer = rank === 'awake' && classId ? deal.offers.get(classId) ?? null : null;\n    const offerStatus = offer ? MODE_BY_ID[offer]?.muOffer?.status : undefined;\n    if (offerStatus) m.applyStatus(offerStatus, 0, 1, 'Mu');\n    w.actors.push(m);\n    apps.push({ id: m.id, classId, rank, offer, t: 0, noted: false }); // offer = the muDeal roll\n  };\n  // THE DEAL's three arcs (engine/muDeal.ts) on THE RING LAW's seats: the\n  // hand, the veiled pool, the cowls — seat order = deal order.\n  deal.awake.forEach((c, i) => seat(apparitionDefId(c.id), c.id, 'awake', rings.awake.angles[i], rings.awake.radius));\n  deal.veiled.forEach((c, i) => seat(apparitionDefId(c.id), c.id, 'veiled', rings.veiled.angles[i], rings.veiled.radius));\n  for (let i = 0; i < deal.faintN; i++) {\n    seat(APPARITION_UNKNOWN_ID, null, 'faint', rings.faint.angles[i], rings.faint.radius);\n  }\n  return apps;\n}","after":"function muSpawnApparitions(w: NativeSceneDirectorHost, sc: SceneRuntime, st: MuState): MuApp[] {\n  return w.nativeSceneBodies ? w.nativeSceneBodies.spawnApparitions(sc,st) : nativeSceneSpawnApparitions(w,sc,st);\n}\n\nexport function nativeSceneSpawnApparitions(w: NativeSceneDirectorHost, sc: SceneRuntime, st: MuState): MuApp[] {\n  const deal = muDeal(w.account);\n  // THE RING LAW (engine/muRing.ts): where each rank STANDS is derived from\n  // how many stand — a readable seat gap widens the crescent, closes it into\n  // a ring, then grows it; ranks stack outward; the globe's wrap keeps its\n  // void beyond the outermost seat.\n  const rings = muRings({ awake: deal.awake.length, veiled: deal.veiled.length, faint: deal.faintN });\n  st.wrap = rings.wrap;\n  const cx = w.arena.w / 2, cy = w.arena.h / 2;\n  const apps: MuApp[] = [];\n  const seat = (defId: string, classId: string | null, rank: MuApp['rank'],\n    th: number, r: number): void => {\n    const m = w.createMonster(defId, 1, 'player');\n    m.pos = w.clampPos(vec(cx + Math.cos(th) * r, cy + Math.sin(th) * r), m.radius);\n    // THE GAZE: born looking at its mark (the wisp) — never a snap later.\n    m.facing = muGazeAngle(w, m);\n    m.facingPrev = m.facing;\n    m.noBounty = true;\n    m.eventKey = sc.eventKey;\n    if (rank === 'veiled') m.applyStatus('mu_veiled', 0, 1, 'Mu');\n    if (rank === 'faint') m.applyStatus('mu_faint', 0, 1, 'Mu');\n    // THE OFFERED CONTRACT: an awake vessel the deal offered under a\n    // contract wears that contract's marker (ModeOfferSpec.status) — the\n    // red ember the player reads before a word is said.\n    const offer = rank === 'awake' && classId ? deal.offers.get(classId) ?? null : null;\n    const offerStatus = offer ? MODE_BY_ID[offer]?.muOffer?.status : undefined;\n    if (offerStatus) m.applyStatus(offerStatus, 0, 1, 'Mu');\n    w.actors.push(m);\n    observeNativeCombatBirth(w,m);\n    apps.push({ id: m.id, classId, rank, offer, t: 0, noted: false }); // offer = the muDeal roll\n  };\n  // THE DEAL's three arcs (engine/muDeal.ts) on THE RING LAW's seats: the\n  // hand, the veiled pool, the cowls — seat order = deal order.\n  deal.awake.forEach((c, i) => seat(apparitionDefId(c.id), c.id, 'awake', rings.awake.angles[i], rings.awake.radius));\n  deal.veiled.forEach((c, i) => seat(apparitionDefId(c.id), c.id, 'veiled', rings.veiled.angles[i], rings.veiled.radius));\n  for (let i = 0; i < deal.faintN; i++) {\n    seat(APPARITION_UNKNOWN_ID, null, 'faint', rings.faint.angles[i], rings.faint.radius);\n  }\n  return apps;\n}"},{"before":"    const col = w.createMonster(s.def, s.level, 'enemy');\n    const at = w.swarmEntryPoint(w.player.pos, [s.spawnDist, s.spawnDist + 60]);\n    col.pos = w.clampPos(vec(at.x, at.y), col.radius);\n    col.noBounty = true;\n    col.eventKey = sc.eventKey;\n    col.aiPost = vec(col.pos.x, col.pos.y);\n    // THE MUSTER STANDS ALONE: the whole kit is banned from the AI picker —\n    // the commander freelances nothing while the director owns the beat (a\n    // direct useSkill never reads the bans, so the ordered verb still flies).\n    for (const inst of col.skills) if (inst) (col.aiSkillBans ??= new Set()).add(inst.def.id);\n    w.actors.push(col);","after":"    const col = spawnSceneColossus(w, sc, s);"},{"before":"  for (let i = w.actors.length - 1; i >= 0; i--) {\n    if (w.actors[i].team !== 'player') w.actors.splice(i, 1);\n  }","after":"  emptySceneField(w);"},{"before":"      for (let i = w.actors.length - 1; i >= 0; i--) {\n        if (w.actors[i].team !== 'player') w.actors.splice(i, 1);\n      }","after":"      emptySceneField(w);"},{"before":"// ---------------------------------------------------------- spawn plumbing --","after":"\nfunction spawnSceneColossus(w: NativeSceneDirectorHost, sc: SceneRuntime, s: SceneReckoningStage): Actor {\n  return w.nativeSceneBodies ? w.nativeSceneBodies.spawnColossus(sc,s) : nativeSceneSpawnColossus(w,sc,s);\n}\nexport function nativeSceneSpawnColossus(w: NativeSceneDirectorHost, sc: SceneRuntime, s: SceneReckoningStage): Actor {\n    const col = w.createMonster(s.def, s.level, 'enemy');\n    const at = w.swarmEntryPoint(w.player.pos, [s.spawnDist, s.spawnDist + 60]);\n    col.pos = w.clampPos(vec(at.x, at.y), col.radius);\n    col.noBounty = true;\n    col.eventKey = sc.eventKey;\n    col.aiPost = vec(col.pos.x, col.pos.y);\n    // THE MUSTER STANDS ALONE: the whole kit is banned from the AI picker —\n    // the commander freelances nothing while the director owns the beat (a\n    // direct useSkill never reads the bans, so the ordered verb still flies).\n    for (const inst of col.skills) if (inst) (col.aiSkillBans ??= new Set()).add(inst.def.id);\n    w.actors.push(col);\n    observeNativeCombatBirth(w,col);\n    return col;\n}\n\nfunction emptySceneField(w: NativeSceneDirectorHost): void {\n  if(w.nativeSceneBodies)w.nativeSceneBodies.emptyField();else nativeSceneEmptyField(w);\n}\nexport function nativeSceneEmptyField(w: NativeSceneDirectorHost): void {\n  for (let i = w.actors.length - 1; i >= 0; i--) {\n    if (w.actors[i].team !== 'player') {\n      const token=observeNativeCombatRetirement(w,[w.actors[i]]);\n      try { w.actors.splice(i,1); finishNativeCombatRetirement(w,token); }\n      finally { cancelNativeCombatRetirement(w,token); }\n    }\n  }\n}\n\n// ---------------------------------------------------------- spawn plumbing --"}]},{"file":"src/engine/nativeSceneDirectorHost.ts","before":"65447fd076b5ffadd95a65a8acbeb47a73b53b234aaa5e252482332279a715c6","after":"444bf0805c68d6632a9a3ab798616b10708591303440249a644d85bce469d286","edits":[{"before":"/** The actual scene director capability surface; shared by native World and\n * retained area's real scene/controller owners. No gameplay implementation. */\nimport type {World,Seat} from './world';\nexport type NativeSceneDirectorHost=Pick<World,\"manifest\"|\"account\"|\"accountDirty\"|\"actors\"|\"ambientCamShift\"|\"applyWaveFrenzy\"|\"arena\"|\"caveMap\"|\"caveReturn\"|\"charDirty\"|\"clampPos\"|\"createMonster\"|\"doodads\"|\"loadZone\"|\"markDoodadsChanged\"|\"player\"|\"playerIdle\"|\"recalcPlayer\"|\"scene\"|\"screenFade\"|\"shake\"|\"swarmEntryPoint\"|\"text\"|\"time\"|\"timeflow\"|\"useSkill\"|\"zone\"> & {readonly seats:readonly Seat[]};\n","after":"/** The actual scene director capability surface; shared by native World and\n * retained area's real scene/controller owners. No gameplay implementation. */\nimport type {World,Seat} from './world';\nexport type NativeSceneDirectorHost=Pick<World,\"manifest\"|\"account\"|\"accountDirty\"|\"actors\"|\"ambientCamShift\"|\"applyWaveFrenzy\"|\"arena\"|\"caveMap\"|\"caveReturn\"|\"charDirty\"|\"clampPos\"|\"createMonster\"|\"doodads\"|\"loadZone\"|\"markDoodadsChanged\"|\"player\"|\"playerIdle\"|\"recalcPlayer\"|\"scene\"|\"screenFade\"|\"shake\"|\"swarmEntryPoint\"|\"text\"|\"time\"|\"timeflow\"|\"useSkill\"|\"zone\"> & {readonly seats:readonly Seat[];readonly nativeSceneBodies?:NativeSceneDirectorBodies};\nexport interface NativeSceneDirectorBodies {\n spawnBody(...args:Tail<Parameters<typeof import('./scenes').nativeSceneSpawnBody>>):ReturnType<typeof import('./scenes').nativeSceneSpawnBody>;\n spawnColossus(...args:Tail<Parameters<typeof import('./scenes').nativeSceneSpawnColossus>>):ReturnType<typeof import('./scenes').nativeSceneSpawnColossus>;\n spawnApparitions(...args:Tail<Parameters<typeof import('./scenes').nativeSceneSpawnApparitions>>):ReturnType<typeof import('./scenes').nativeSceneSpawnApparitions>;\n emptyField():void;\n}\ntype Tail<T extends unknown[]> = T extends [unknown,...infer R] ? R : never;\n"}]}]} as const;
